 void BuildModernMenuEnvironment(){if(!modernMenuBacking){modernMenuBacking=W.Rect(transform,"Modern menu full-screen backing",0,0,1,1);modernMenuBacking.anchorMin=Vector2.zero;modernMenuBacking.anchorMax=Vector2.one;modernMenuBacking.sizeDelta=Vector2.zero;modernMenuBacking.anchoredPosition=Vector2.zero;modernMenuBacking.SetAsFirstSibling();var backing=modernMenuBacking.gameObject.AddComponent<Image>();backing.color=new Color(.022f,.025f,.043f);backing.raycastTarget=true;var texture=Resources.Load<Texture2D>("RiftMenu/RiftBackground");if(texture){var background=RiftWidgets.Rect(modernMenuBacking,"Approved full-width Rift landscape",0,0,1920,1080).gameObject.AddComponent<RawImage>();background.texture=texture;background.raycastTarget=false;var rect=background.rectTransform;rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(.5f,.5f);rect.anchoredPosition=Vector2.zero;var fit=background.gameObject.AddComponent<AspectRatioFitter>();fit.aspectMode=AspectRatioFitter.AspectMode.EnvelopeParent;fit.aspectRatio=(float)texture.width/texture.height;}var overlay=RiftWidgets.Rect(modernMenuBacking,"Background readability overlay",0,0,1920,1080).gameObject.AddComponent<Image>();overlay.rectTransform.anchorMin=Vector2.zero;overlay.rectTransform.anchorMax=Vector2.one;overlay.rectTransform.sizeDelta=Vector2.zero;overlay.rectTransform.anchoredPosition=Vector2.zero;overlay.color=new Color(0,0,0,MenuBackgroundOpacity);overlay.raycastTarget=false;}var environment=W.Rect(Design,"Modern menu environment",0,0,1920,1080);environment.SetSiblingIndex(Stage?Stage.transform.GetSiblingIndex():0);if(Stage)Stage.ConfigureMainMenuPresentation();
  content=W.Rect(Design,"Screen",36,168,1848,810);toast=W.Label(Design,"",590,1008,1200,40,18,new Color(.86f,.75f,1));Navigate(HubPage.Home);Fit();}
 RiftMapSurface MenuSurface(Transform parent,string name,float x,float y,float width,float height,Color fill,Color border,float glow=0){var surface=W.Rect(parent,name,x,y,width,height).gameObject.AddComponent<RiftMapSurface>();surface.Fill=fill;surface.Border=border;surface.Radius=10;surface.Glow=glow;surface.raycastTarget=false;return surface;}
 Button MenuAction(Transform parent,string title,string description,float x,float y,float width,float height,Action action,HUDShape icon,bool primary=false){var surface=MenuSurface(parent,"Main menu "+title,x,y,width,height,new Color(primary?.14f:.055f,primary?.065f:.06f,primary?.24f:.09f,.78f),primary?new Color(.66f,.4f,1):new Color(.4f,.4f,.5f,.75f),primary?8:0);surface.raycastTarget=true;var button=surface.gameObject.AddComponent<Button>();button.targetGraphic=surface;var colors=button.colors;colors.normalColor=Color.white;colors.highlightedColor=new Color(1.2f,1.13f,1.4f);colors.selectedColor=colors.highlightedColor;colors.pressedColor=new Color(.7f,.65f,.86f);button.colors=colors;button.onClick.AddListener(()=>StartCoroutine(DeferMainMenuAction(action)));float iconSize=height<60?22:36;var graphic=W.Rect(surface.transform,"Action icon",24,(height-iconSize)*.5f,iconSize,iconSize).gameObject.AddComponent<RiftHUDGraphic>();graphic.Shape=icon;graphic.color=new Color(.84f,.8f,.98f);graphic.Border=graphic.color;graphic.Thickness=2;graphic.raycastTarget=false;if(primary)graphic.rectTransform.localRotation=Quaternion.Euler(0,0,-90);W.Label(surface.transform,title,86,0,width-130,height,30,new Color(.95f,.94f,1));W.Label(surface.transform,"›",width-38,0,28,height,30,new Color(.75f,.7f,.9f));var tip=surface.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title=title;tip.Description=description;var focus=surface.gameObject.AddComponent<RiftMainMenuFocus>();focus.Primary=primary;return button;}
 void ModernHome(){var root=W.Rect(content,"Modern main menu",-36,-168,1920,1080);MenuSurface(root,"Main navigation glass",36,48,500,984,new Color(.037f,.04f,.065f,.83f),new Color(.48f,.47f,.6f,.8f));var texture=Resources.Load<Texture2D>("RiftMenu/Logo");if(texture){var logo=W.Rect(root,"Approved ROM logo",70,115,430,143).gameObject.AddComponent<RawImage>();logo.texture=texture;logo.raycastTarget=false;logo.rectTransform.sizeDelta=new Vector2(430,430f*texture.height/texture.width);}
  W.Label(root,"EL RIFT · EXPLORACIÓN",84,268,400,28,14,new Color(.7f,.65f,.82f));
  var play=MenuAction(root,"Jugar","Iniciá una partida en El Rift.",68,330,436,88,Deploy,HUDShape.Arrow,true);
