  W.Label(root,"↑ ↓ para navegar  ·  Enter para elegir",70,968,430,35,16,new Color(.7f,.68f,.79f));
  var identity=MenuSurface(root,"Selected skin identity",1540,864,344,160,new Color(.035f,.038f,.06f,.86f),new Color(.49f,.47f,.64f,.8f));string name=Roster.Active.Available?RiftSkinIdentity.Name(Roster.Active.Skin):RiftSkinIdentity.Name(1);W.Label(identity.transform,name,24,18,240,52,36,new Color(.97f,.95f,1));W.Label(identity.transform,"Warrior",24,74,240,40,23,new Color(.72f,.69f,.84f));W.Image(identity.transform,"Identity divider",24,120,296,1,new Color(.35f,.33f,.45f));W.Label(identity.transform,Roster.Active.Available?"Skin seleccionada":"Elegí un Warrior para jugar",24,128,296,24,15,new Color(.7f,.67f,.8f));W.Label(root,"Versión "+Application.version,650,1034,1200,26,15,new Color(.73f,.71f,.81f));
  if(string.IsNullOrEmpty(homePanel)){if(EventSystem.current)EventSystem.current.SetSelectedGameObject(play.gameObject);RiftAbilityTooltip.HideAll();return;}
