 }
 void MenuExit(){if(Application.platform==RuntimePlatform.WebGLPlayer)Dialog("Salir","Para salir de la versión web, cerrá la pestaña del juego.",null);else Dialog("Salir de Riftbreakers","¿Querés cerrar el juego?",()=>Application.Quit());}
 }
 // This state is scoped to menu controls. It does not mutate the shared button theme.
 public sealed class RiftMainMenuFocus:MonoBehaviour,IPointerEnterHandler,IPointerExitHandler,ISelectHandler,IDeselectHandler {
  public bool Primary;bool hovered,selected;void Refresh(){var surface=GetComponent<RiftMapSurface>();surface.Glow=Primary?8:hovered||selected?5:0;surface.Border=Primary||hovered||selected?new Color(.66f,.4f,1):new Color(.4f,.4f,.5f,.75f);surface.SetVerticesDirty();}
  public void OnPointerEnter(PointerEventData e){hovered=true;Refresh();}public void OnPointerExit(PointerEventData e){hovered=false;Refresh();}public void OnSelect(BaseEventData e){selected=true;Refresh();}public void OnDeselect(BaseEventData e){selected=false;Refresh();}
 }
